CREATE SCHEMA IF NOT EXISTS raw;

CREATE TABLE IF NOT EXISTS raw._ingestion_log (
    log_id        bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    batch_id      uuid NOT NULL,
    table_name    text NOT NULL,
    source_file   text NOT NULL,
    source_sha256 char(64),
    status        text NOT NULL CHECK (status IN ('loaded', 'skipped', 'failed')),
    rows_loaded   bigint,
    started_at    timestamptz NOT NULL,
    finished_at   timestamptz NOT NULL,
    message       text
);
CREATE INDEX IF NOT EXISTS _ingestion_log_table_idx
    ON raw._ingestion_log (table_name, status, finished_at DESC);

